"""Phase 3 report: applies the preregistered gates (docs/phase3_plan.md section 8) mechanically and writes results/phase3/report_tables.md + criteria_verdict.json."""
import json
from pathlib import Path

import numpy as np

from causal_subspaces.mediation import analysis as AN

R = Path(__file__).resolve().parents[1] / "results/phase3"
PT = json.load(open(R / "patching.json")); PA = np.load(R / "patching_arrays.npz", allow_pickle=True)
AB = json.load(open(R / "ablation.json")) if (R / "ablation.json").exists() else None
SP = json.load(open(R / "supp.json")) if (R / "supp.json").exists() else None
PL = json.load(open(R / "pilot.json"))
md, ml = [], None
ml = md.append
ml("# Phase 3 report tables (auto-generated by scripts/phase3_report.py)\n")
ml(f"Pilot (validation pairs, num_orig; Stage 1): preflight hook-order verified = {PL['preflight_order_ok']}; pilot TE = {json.dumps(PL['pilot_TE'])}\n")
FAMS = ("random", "act", "align")
verdict = {"per_format": {}}
f2 = lambda d, k: ("%.3f" % d[k]) if (not d.get("undefined") and k in d) else "undef"
holm_in = {}
cmp_store = {}
for fmt, o in PT["formats"].items():
    ml(f"\n## Patching — {fmt}  (n trials {o['n_trials']}; test-content aligned pairs: held out from the MLP ranking, previously examined in Phase 2.5/2.6 attention experiments)\n")
    for hn, ent in o["headsets"].items():
        sets = ent["sets"]; sg = PA[f"{fmt}|sgn"]
        ml(f"\n### {hn}   noise floor (self-restore) {ent['noise_floor']}; TE coordinate {ent['TE']['c']:.2f}, margin {ent['TE']['margin']:.2f}\n")
        rep = ent["reported_signed_aggregated"]
        ml("Reported separately (aggregated, signed toward the source): direct attention-layer-22 write change " + f"{rep['direct_attn22_change']:+.3f}; MLP22 write change {rep['mlp22_write_change']:+.3f}; of which U22 verdict-directed write change {rep['U22_write_change']:+.3f} (mean |δa| over U22 {rep['U22_mean_abs_dA']:.3f}); residual-coordinate change {rep['coordinate_change']:+.3f}; final margin change {rep['margin_change']:+.3f}.\n")
        ml("| set | coord R [95 % CI] | coord B | coord S | coord J | margin R [95 % CI] | margin B | margin S | margin J (interaction) | share of induced write change |\n|---|---|---|---|---|---|---|---|---|---|")
        names = ["U22", "full22", "complement", "oracle", "delta_matched", "dose16", "dose64", "dose128"] + [k for k in ("U_all", "full_all") if k in sets]
        for nm in names:
            if nm not in sets: continue
            c, m = sets[nm]["c"], sets[nm]["margin"]
            ci = lambda d: (f"[{d['R_ci'][0]:.3f}, {d['R_ci'][1]:.3f}]" if "R_ci" in d else "")
            ml(f"| {nm} | {f2(c, 'R')} {ci(c)} | {f2(c, 'B')} | {f2(c, 'S')} | {f2(c, 'J')} | {f2(m, 'R')} {ci(m)} | {f2(m, 'B')} | {f2(m, 'S')} | {f2(m, 'J')} | {ent['concentration']['shares'].get(nm, float('nan')):.3f} |")
        fam_stats = {}
        for fam in FAMS:
            ks = [k for k in sets if k.rstrip('0123456789') == fam]
            if not ks: continue
            for oc in ("c", "margin"):
                vals = [sets[k][oc]["R"] for k in ks if not sets[k][oc].get("undefined")]
                fam_stats[(fam, oc)] = vals
        ml("\nControl families (R mean [min, max], n draws): " + "; ".join(f"{fam}/{oc}: {np.mean(v):+.3f} [{np.min(v):+.3f}, {np.max(v):+.3f}] (n={len(v)})" for (fam, oc), v in fam_stats.items()))
        ml("Concentration of the induced layer-22 signed write change: U22 " + f"{ent['concentration']['shares']['U22']:.3f}; control families " + json.dumps({k: {kk: round(vv, 4) for kk, vv in v.items() if kk != 'n'} for k, v in ent['concentration']['families'].items()}) + f"; ratio U22 / pooled control mean {ent['concentration']['U22_vs_control_mean_ratio']:.1f}; Spearman(Phase-1 |Δ|, induced |Δs|) = {ent['concentration']['rank_corr_phase1_vs_induced']:.3f}.")
        st = ent["strength"]
        ml(f"Intervention strength: ‖Δ MLP input after post_attention_layernorm‖ mean {st['mlp_input_change_norm_mean']:.2f} (clean norm {st['mlp_input_norm_clean']:.1f}); Σ|δa| over U22 {st['sum_abs_dA'].get('U22', float('nan')):.2f}, oracle {st['sum_abs_dA'].get('oracle', float('nan')):.2f}, δ-matched {st['sum_abs_dA'].get('delta_matched', float('nan')):.2f}, random0 {st['sum_abs_dA'].get('random0', float('nan')):.3f}, act0 {st['sum_abs_dA'].get('act0', float('nan')):.3f}, align0 {st['sum_abs_dA'].get('align0', float('nan')):.3f}; Σ|g·δa|: U22 {st['sum_abs_gdA'].get('U22', float('nan')):.2f}, random0 {st['sum_abs_gdA'].get('random0', float('nan')):.3f}.")
        ml(f"Control-matching quality (mean |standardised mean difference| of matching features; response-selected controls flagged): {json.dumps({k: {kk: round(vv, 3) for kk, vv in v.items()} for k, v in ent['matching_quality_mean_abs_smd'].items()})}\n")
        if hn == "S8_L22":
            # paired-bootstrap CI of U22 - mean(control) and z-tests per family/outcome
            clean = {oc: PA[f"{fmt}|{hn}|clean|{oc}"] for oc in ("c", "margin")}; inter = {oc: PA[f"{fmt}|{hn}|inter|{oc}"] for oc in ("c", "margin")}
            for fam in FAMS:
                ks = [k for k in sets if k.rstrip('0123456789') == fam]
                for oc in ("c", "margin"):
                    y10 = {k: PA[f"{fmt}|{hn}|{k}|Y10|{oc}"] for k in ["U22"] + ks}
                    Rf = lambda k, rows: float(((sg * (inter[oc] - y10[k]))[rows].mean()) / (sg * (inter[oc] - clean[oc]))[rows].mean())
                    rg = np.random.default_rng(5); n = len(sg); diffs = []
                    for _ in range(300):
                        rows = rg.integers(0, n, n); diffs.append(Rf("U22", rows) - np.mean([Rf(k, rows) for k in ks]))
                    cmp = AN.compare_to_controls(sets["U22"][oc]["R"], [sets[k][oc]["R"] for k in ks])
                    cmp.update(diff_ci=[float(np.quantile(diffs, .025)), float(np.quantile(diffs, .975))])
                    cmp_store[(fmt, fam, oc)] = cmp; holm_in[f"{fmt}|{fam}|{oc}"] = cmp["p_normal"] if np.isfinite(cmp["p_normal"]) else 1.0
verdict["holm_adjusted"] = AN.holm(holm_in)
ml("\n## Comparison of U22 rescue with the three pre-intervention control families (S8_L22; 20 draws each; empirical p_min = 1/21 = 0.048 is NOT significance; Holm over the 12 comparisons)\n")
ml("| format | family | outcome | U22 R | control mean | control max | above all draws | empirical p | z (Shapiro p) | Holm-adj p | bootstrap CI of U22 − control mean |\n|---|---|---|---|---|---|---|---|---|---|---|")
for (fmt, fam, oc), c in cmp_store.items():
    u = PT["formats"][fmt]["headsets"]["S8_L22"]["sets"]["U22"][oc]["R"]
    ml(f"| {fmt} | {fam} | {oc} | {u:.3f} | {c['control_mean']:+.4f} | {c['control_max']:+.4f} | {c['above_all']} | {c['empirical_p']:.3f} | {c['z']:.0f} ({c['shapiro_p']:.2f}) | {verdict['holm_adjusted'][f'{fmt}|{fam}|{oc}']:.2g} | [{c['diff_ci'][0]:.3f}, {c['diff_ci'][1]:.3f}] |")
# ---------------- mediation gate M ----------------
M = {}
for fmt, o in PT["formats"].items():
    e = o["headsets"]["S8_L22"]; s = e["sets"]; conc = e["concentration"]
    ctrl_mean = np.mean([v for f in conc["families"].values() for v in [f["mean"]]]); ctrl_max = max(f["max"] for f in conc["families"].values())
    m1 = bool(conc["shares"]["U22"] >= 0.50 and conc["shares"]["U22"] >= 3 * max(ctrl_mean, 1e-9) and conc["shares"]["U22"] > ctrl_max)
    m2 = bool(not s["U22"]["c"].get("undefined") and s["U22"]["c"]["R"] >= 0.40); m3 = bool(not s["U22"]["margin"].get("undefined") and s["U22"]["margin"]["R"] >= 0.30)
    m4 = bool(all(cmp_store[(fmt, fam, oc)]["above_all"] and verdict["holm_adjusted"][f"{fmt}|{fam}|{oc}"] < 0.05 and cmp_store[(fmt, fam, oc)]["diff_ci"][0] > 0 and cmp_store[(fmt, fam, oc)]["control_mean"] <= 0.10 for fam in FAMS for oc in ("c", "margin")))
    m5 = bool(s["U22"]["c"].get("S", -1) >= 0.25 and s["U22"]["margin"].get("S", -1) >= 0.25)
    bypass = {oc: s["U22"][oc].get("B") for oc in ("c", "margin")}
    M[fmt] = dict(M1_concentration=m1, M2_coordinate_rescue=m2, M3_margin_rescue=m3, M4_beats_controls=m4, M5_transplant=m5, passed=bool(m1 and m2 and m3 and m4 and m5), bypass=bypass,
                  bypass_dominated={oc: bool(b is not None and b >= 0.70) for oc, b in bypass.items()}, R_full_bound={oc: s["full22"][oc].get("R") for oc in ("c", "margin")}, interaction_margin_J=s["U22"]["margin"].get("J"))
    verdict["per_format"][fmt] = M[fmt]
ml("\n## Mediation gate (M), S8_L22 / U22, patching, last query row\n```json\n" + json.dumps(M, indent=1, default=float) + "\n```")
Mp = all(v["passed"] for v in M.values())
# ---------------- generalization G and selectivity V from ablation ----------------
G, V = {"evaluated": False}, {"evaluated": False}
if AB:
    ent = AB["headsets"]["S8_L22"]; G = {"evaluated": True}
    ml("\n## Ablation-based mediation (S8_L22 head ablation, class-gap scale; confirmatory class-level set)\n")
    ml("| task | outcome | TE (gap reduction) | U22 rescue R [CI] | B | S | J | full22 R | oracle R | complement R | control mean R (random/act/align) |\n|---|---|---|---|---|---|---|---|---|---|---|")
    for tk, tko in ent["tasks"].items():
        for oc, row in tko.items():
            u = row["U22"]; ctrls = [row[k]["R"] for k in row if k.rstrip('0123456789') in FAMS and not row[k].get("undefined")]
            ci = f"[{u['R_ci'][0]:.3f}, {u['R_ci'][1]:.3f}]" if "R_ci" in u else ""
            ml(f"| {tk} | {oc} | {u['TE']:.2f} | {f2(u, 'R')} {ci} | {f2(u, 'B')} | {f2(u, 'S')} | {f2(u, 'J')} | {f2(row['full22'], 'R')} | {f2(row['oracle'], 'R')} | {f2(row['complement'], 'R')} | {(np.mean(ctrls) if ctrls else float('nan')):+.3f} |")
    for tk in ("logic_num_orig", "logic_num_rev", "localizer"):
        for oc in ("c", "margin"):
            u = ent["tasks"][tk][oc]["U22"]; G[f"{tk}|{oc}"] = bool((not u.get("undefined")) and u["R"] >= 0.25)
    G["passed"] = bool(all(v for k, v in G.items() if k != "evaluated"))
    vf = ent["verdict_free_mean_shifts"]; V = {"evaluated": True, "tasks": {}}
    ml("\n### Verdict-free negative controls (mean margin shifts; TE below the 5-logit floor makes the ratio undefined)\n\n| task | head-ablation mean shift (TE) | U22-restored shift | R = (TE − restored)/TE | random-restored shift range | note |\n|---|---|---|---|---|---|")
    ok_all = True
    for tk, v in vf.items():
        te, rs = v["head_ablation_mean_shift"], v["U22_restored_mean_shift"]; undefined = abs(te) < AN.FLOORS["margin"]
        Rv = (te - rs) / te if te != 0 else float("nan")
        V["tasks"][tk] = dict(TE=te, R=Rv, undefined=undefined)
        ml(f"| {tk} | {te:+.3f} | {rs:+.3f} | {Rv:+.3f} | {v['random_restored_mean_shift_range']} | {'undefined: |TE| < 5 logits floor' if undefined else ''} |")
    # class-gap version of the same negative controls (the plan's "head-ablation shifts" admits both readings; both are applied literally)
    V["class_gap"] = {}
    for tk in ("mmlu_binary", "stroop", "word_recall_48"):
        u = ent["tasks"][tk]["margin"]["U22"]; V["class_gap"][tk] = dict(TE=u["TE"], undefined=bool(u.get("undefined")), R=None if u.get("undefined") else u["R"])
    ml("\n| task (class-gap scale) | head-ablation class-gap reduction TE | U22 rescue R |\n|---|---|---|")
    for tk, v in V["class_gap"].items(): ml(f"| {tk} | {v['TE']:.2f} | {('%.3f' % v['R']) if v['R'] is not None else 'undefined (|TE| < 5 logits)'} |")
    allv = [t for t in V["tasks"].values() if not t["undefined"]] + [t for t in V["class_gap"].values() if not t["undefined"]]
    V["evaluable"] = bool(allv)
    V["passed"] = bool(V["evaluable"] and all((t["R"] <= 0.15) for t in allv))
    V["failed_tasks"] = [tk for tk, t in V["class_gap"].items() if not t["undefined"] and t["R"] > 0.15] + [tk for tk, t in V["tasks"].items() if not t["undefined"] and t["R"] > 0.15]
    # also: logic-adjacent PrOntoQA is reported through raw gap reductions only
    ml("\n### Verdict-free task class gaps (head ablation barely changes them)\n" + "; ".join(f"{tk}: TE_gap {ent['tasks'][tk]['margin']['U22']['TE']:+.2f}" for tk in ("mmlu_binary", "stroop", "word_recall_48")))
verdict["G_generalization"] = G; verdict["V_selectivity"] = V; verdict["M_all_formats"] = bool(Mp)
# ---------------- supplementary ----------------
if SP:
    ml("\n## Supplementary (exploratory)\n")
    for hn, e in SP.get("earlier_layer_heads", {}).items():
        u = e["sets"]["U_geL"]; f = e["sets"]["full_geL"]
        ml(f"- {hn} (mediators at layers {e['layers']}): U_geL coordinate R {f2(u['c'], 'R')}, B {f2(u['c'], 'B')}; margin R {f2(u['margin'], 'R')}, B {f2(u['margin'], 'B')}; full-layers bound R_c {f2(f['c'], 'R')}, R_m {f2(f['margin'], 'R')}; TE c/m {u['c']['TE']:.2f}/{u['margin']['TE']:.2f}; random-restored R_c "
           f"{np.mean([e['sets'][k]['c']['R'] for k in e['sets'] if k.startswith('random') and not e['sets'][k]['c'].get('undefined')] or [float('nan')]):+.3f}")
    for fmt, c in SP.get("coordinate_clamp", {}).items():
        ml(f"- coordinate clamp ({fmt}): TE coordinate/margin {c['TE']['c']:.2f}/{c['TE']['margin']:.2f}; with the d_c coordinate reset to its clean value the coordinate effect is {c['effect_with_coordinate_clamped']['c']:+.3f} and the margin effect {c['effect_with_coordinate_clamped']['margin']:+.2f} (fraction of the margin effect not passing through the verdict coordinate: {c['fraction_margin_effect_not_through_dc_coordinate']})")
    a = SP.get("all_query_rows", {}).get("U22")
    if a: ml(f"- all query rows (S8_L22, num_orig): U22 coordinate R {f2(a['c'], 'R')}, margin R {f2(a['margin'], 'R')}, margin S {f2(a['margin'], 'S')}, margin J {f2(a['margin'], 'J')}")
# ---------------- outcome table ----------------
partial = any((not v["passed"]) and (v["M2_coordinate_rescue"] or v["M3_margin_rescue"] or (v["bypass"]["c"] is not None and v["bypass"]["c"] < 0.85)) for v in M.values())
if Mp and G.get("passed") and V.get("passed"): outcome = "MEDIATION SUPPORTED AND VERDICT-SELECTIVE"
elif Mp and (not G.get("passed", False)): outcome = "MIXED: mediation established in the patching design, but generalization (G) not met / not evaluated"
elif Mp: outcome = "MIXED: mediation established, specificity (V) not established" + (" (V not evaluable: head-ablation effects on verdict-free tasks are below the validity floor)" if not V.get("evaluable", False) else f" (V failed on {V.get('failed_tasks')})")
elif partial: outcome = "MIXED / PARTIAL"
else: outcome = "MEDIATION NOT SUPPORTED"
verdict["outcome"] = outcome
ml(f"\n## Outcome (mechanical, docs/phase3_plan.md section 8)\nM (both formats): {Mp}; G: {G.get('passed')}; V: {V.get('passed')} (evaluable: {V.get('evaluable')}).\n**{outcome}.**")
(R / "report_tables.md").write_text("\n".join(md)); json.dump(verdict, open(R / "criteria_verdict.json", "w"), indent=1, default=lambda o: bool(o) if isinstance(o, np.bool_) else float(o))
print("\n".join(md[-60:]))
